import { useEffect, useState } from "react";
import "./App.css";

const initialTransactions = [
    {
        type: "deposit",
        amount: 10000,
        date: new Date().toISOString().split("T")[0],
    },
    {
        type: "buy",
        stock: "TSLA",
        shares: 10,
        price: 274,
        amount: 2740,
        date: new Date().toISOString().split("T")[0],
    },
];

const TransactionTypes = Object.freeze({
    BUY: "buy",
    SELL: "sell",
    DEPOSIT: "deposit",
    WITHDRAW: "withdraw",
});

function App() {
    const [transactions, setTransactions] = useState(initialTransactions);
    const [balance, setBalance] = useState(0);
    const [invested, setInvested] = useState(0);
    const [injected, setInjected] = useState(0);
    const [profit, setProfit] = useState(0);

    function handleCreateTransaction(type, stock, shares, price, amount, date) {
        const newTransaction = {
            type,
            stock,
            shares,
            price,
            amount,
            date,
        };
        setTransactions((cur) => [...cur, newTransaction]);
    }

    function calculateInjected(transactions) {
        let injected = 0;
        transactions.forEach((transaction) => {
            switch (transaction.type) {
                case TransactionTypes.DEPOSIT:
                    injected += transaction.amount;
                    break;
                case TransactionTypes.WITHDRAW:
                    injected -= transaction.amount;
                    break;
                default:
                    break;
            }
        });
        return injected;
    }

    useEffect(() => {
        const balances = calculateBalance(transactions);
        setBalance(balances.balance);
        setInjected(balances.injected);
        setInvested(balances.invested);
        setProfit(balances.profit);
    }, [transactions]);

    return (
        <div className="App">
            <h1>Trading Journal</h1>
            <Balances
                balance={balance}
                injected={injected}
                invested={invested}
                profit={profit}
            />
            <TradeForm onCreateTransaction={handleCreateTransaction} />
            <DepositAndWithdrawalForm
                onCreateTransaction={handleCreateTransaction}
            />
            <TransactionTable />
            <TradesTable />
        </div>
    );
}

function Balances({ balance, invested, injected, profit }) {
    return (
        <div>
            <div>
                <label>Account Balance</label>
                <input type="text" disabled value={balance} />
            </div>
            <div>
                <label>Invested</label>
                <input type="text" disabled value={invested} />
            </div>
            <div>
                <label>Injected</label>
                <input type="text" disabled value={injected} />
            </div>
            <div>
                <label>Profit</label>
                <input type="text" disabled value={profit} />
            </div>
        </div>
    );
}

function TradeForm({ onCreateTransaction }) {
    const [transactionType, setTransactionType] = useState(
        TransactionTypes.BUY
    );
    const [stock, setStock] = useState("");
    const [shares, setShares] = useState("");
    const [price, setPrice] = useState("");
    const [date, setDate] = useState(new Date().toISOString().split("T")[0]);

    const total = shares * price;

    function handleSubmit(e) {
        e.preventDefault();
        if (!transactionType || !stock || !shares || !price || !date) return;

        onCreateTransaction(transactionType, stock, shares, price, total, date);
    }

    function handleChangeStock(event) {
        var inputValue = event.charCode;
        if (
            !(inputValue >= 65 && inputValue <= 120) &&
            inputValue !== 32 &&
            inputValue !== 0
        ) {
            event.preventDefault();
        }
        setStock(event.target.value.toUpperCase());
    }

    function handleChangeShares(value) {
        if (isNaN(value)) return;
        setShares(Number(value));
    }

    function handleChangePrice(value) {
        if (isNaN(value)) return;
        setPrice(Number(value));
    }

    return (
        <form className="form" onSubmit={(e) => handleSubmit(e)}>
            <h2>Enter a Trade</h2>
            <div>
                <input
                    type="radio"
                    id="buy"
                    checked={transactionType === TransactionTypes.BUY}
                    onChange={() => setTransactionType(TransactionTypes.BUY)}
                />
                <label htmlFor="buy">Buy</label>
                <input
                    type="radio"
                    id="sell"
                    checked={transactionType === TransactionTypes.SELL}
                    onChange={() => setTransactionType(TransactionTypes.SELL)}
                />
                <label htmlFor="sell">Sell</label>
            </div>
            <div>
                <label>Stock</label>
                <input
                    type="text"
                    value={stock}
                    onChange={(e) => handleChangeStock(e)}
                />
            </div>
            <div>
                <label>Shares</label>
                <input
                    type="text"
                    value={shares}
                    onChange={(e) => handleChangeShares(e.target.value)}
                />
            </div>
            <div>
                <label>Price</label>
                <input
                    type="text"
                    value={price}
                    onChange={(e) => handleChangePrice(e.target.value)}
                />
            </div>
            <div>
                <label>Total</label>
                <input type="text" disabled value={total} />
            </div>
            <div>
                <label>Date</label>
                <input
                    type="date"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                />
            </div>
            <button>Submit</button>
        </form>
    );
}

function DepositAndWithdrawalForm({ onCreateTransaction }) {
    const [transactionType, setTransactionType] = useState(
        TransactionTypes.DEPOSIT
    );
    const [amount, setAmount] = useState(0);
    const [date, setDate] = useState(new Date().toISOString().split("T")[0]);

    function handleSubmit(e) {
        e.preventDefault();
        console.log(transactionType);
        console.log(amount);
        console.log(date);
        onCreateTransaction(transactionType, null, null, null, amount, date);
    }

    function handleChangeAmount(value) {
        if (isNaN(value)) return;
        setAmount(Number(value));
    }

    return (
        <form className="form" onSubmit={(e) => handleSubmit(e)}>
            <h2>Deposit or Withdraw</h2>
            <div>
                <input
                    type="radio"
                    id="deposit"
                    checked={transactionType === TransactionTypes.DEPOSIT}
                    onChange={() =>
                        setTransactionType(TransactionTypes.DEPOSIT)
                    }
                />
                <label htmlFor="deposit">Deposit</label>
                <input
                    type="radio"
                    id="withdraw"
                    checked={transactionType === TransactionTypes.WITHDRAW}
                    onChange={() =>
                        setTransactionType(TransactionTypes.WITHDRAW)
                    }
                />
                <label htmlFor="withdraw">Withdraw</label>
            </div>
            <div>
                <label>Amount</label>
                <input
                    type="text"
                    value={amount}
                    onChange={(e) => handleChangeAmount(e.target.value)}
                />
            </div>
            <div>
                <label>Date</label>
                <input
                    type="date"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                />
            </div>
            <button>Submit</button>
        </form>
    );
}

function TransactionTable() {
    return (
        <div>
            <h2>Transactions</h2>
            <table></table>
        </div>
    );
}

function TradesTable() {
    return (
        <div>
            <h2>Trades</h2>
            <table></table>
        </div>
    );
}

export default App;
